<?php
declare(strict_types=1);
namespace App\Tests\Integration;
use App\Application\OfferPdfService;use App\Application\OfferService;use App\Application\OrderService;use App\Domain\Calculation\PriceCalculator;use App\Domain\Offer\OfferCalculator;use App\Domain\Offer\OfferValidator;use App\Domain\Order\OrderValidationException;use App\Infrastructure\Database\ConnectionFactory;use App\Infrastructure\Database\Migrator;use App\Infrastructure\Persistence\DocumentSettingsRepository;use App\Infrastructure\Persistence\NumberRangeRepository;use App\Infrastructure\Persistence\OfferJsonStore;use App\Infrastructure\Persistence\OfferRepository;use App\Infrastructure\Persistence\OrderRepository;use App\Infrastructure\Persistence\ProjectRepository;use App\Support\Clock;use App\Support\Uuid;use App\Tests\TestCase;
final class OrderManagementTest extends TestCase
{
 public function testOfferAndDirectOrdersOptionalProjectsAndStatusHistory():void{$root=dirname(__DIR__,2);$tmp=sys_get_temp_dir().'/calight-orders-'.bin2hex(random_bytes(6));mkdir($tmp,0770,true);try{$pdo=ConnectionFactory::create($tmp.'/db.sqlite');(new Migrator($pdo,$root.'/migrations'))->migrate();$customer=Uuid::v4();$now=Clock::now();$pdo->prepare("INSERT INTO customers(id,customer_number,customer_type,company_name,created_at,updated_at) VALUES(:id,'10003','company','Kunde',:now,:now)")->execute(['id'=>$customer,'now'=>$now]);$offers=new OfferRepository($pdo);$projects=new ProjectRepository($pdo);$validator=new OfferValidator();$calculator=new OfferCalculator(new PriceCalculator());$numbers=new NumberRangeRepository($pdo);$offerService=new OfferService($pdo,$projects,$offers,new OfferJsonStore($tmp.'/offers',$validator),$calculator,$numbers,new OfferPdfService($pdo,new DocumentSettingsRepository($pdo),$validator,$calculator));$id=$offerService->createDraft(null,'Projektfreies Angebot',$customer);$loaded=$offerService->loadDraft($id);$document=$loaded['offer'];$document['nodes']=[['id'=>Uuid::v4(),'type'=>'position','positionType'=>'normal','workStatus'=>'done','shortText'=>'Leistung','longText'=>'','quantity'=>'1.000','unit'=>'Stk.','manualUnitPrice'=>'100.00','components'=>[]]];$etag=$offerService->saveDraft($id,$document,$loaded['etag']);$offerService->submitOffer($id,$etag,null,'2026-11-09',true);$offerService->changeStatus($id,'submitted','commissioned');$orders=new OrderService($pdo,new OrderRepository($pdo),$offers,$offerService,$numbers);$offerOrder=$orders->createFromOffer($id);$this->assertSame('offer',$offerOrder['orderType']);$this->assertSame(null,$offerOrder['projectId']);$this->assertSame('100.00',$offerOrder['basis']['calculation']['netTotal']);$this->assertThrows(OrderValidationException::class,fn()=>$orders->createFromOffer($id));$regie=$orders->createRegie(['customerId'=>$customer,'projectId'=>'','title'=>'Störung','orderDate'=>'2026-11-09']);$this->assertSame('regie',$regie['orderType']);$changed=$orders->changeStatus($regie['id'],'open','in_progress');$this->assertSame('in_progress',$changed['status']);$this->assertTrue(count($changed['history'])>=2);}finally{$this->remove($tmp);}}
 private function remove(string $path):void{if(!is_dir($path))return;foreach(scandir($path)?:[] as $item){if($item==='.'||$item==='..')continue;$child=$path.'/'.$item;is_dir($child)?$this->remove($child):unlink($child);}rmdir($path);}
}
